<script setup lang="ts">
import { Check, ChevronLeft, ChevronRight, Clipboard, KeyRound, Link2, LockKeyhole, Search, ShieldCheck, UserRoundCheck, UserRoundX, Users, X } from '@lucide/vue';
const config = useRuntimeConfig();
const { token, user } = useWorkspaceSession();
const { openContextMenu, copyText } = useContextMenu();
const result = ref<any>({ items: [], total: 0, page: 1, pages: 1, totals: { all: 0, staff: 0, b2c: 0, b2b: 0, pendingChanges: 0 } });
const requests = ref<any[]>([]);
const type = ref<'ALL'|'STAFF'|'B2C'|'B2B'>('ALL');
const search = ref('');
const page = ref(1);
const busy = ref(false);
const selected = ref<any>(null);
const notice = ref('');
const error = ref('');
const resetInfo = ref<any>(null);
const temporary = reactive({ currentAdminPassword: '', temporaryPassword: '' });
const edit = reactive({ firstName: '', lastName: '', email: '', phone: '' });
let searchTimer: ReturnType<typeof setTimeout> | undefined;
const headers = computed(() => ({ Authorization: `Bearer ${token.value}` }));
const roleLabels: Record<string,string> = { ADMIN:'Администратор платформы',CONTENT_MANAGER:'Контент-менеджер',MANAGER_B2B:'Менеджер B2B',MANAGER_SALES:'Менеджер продаж',MARKETPLACE_MANAGER:'Менеджер маркетплейсов',SUPERVISOR:'Руководитель направления',EXECUTIVE:'Руководитель компании',IT_SUPPORT:'IT-поддержка',CURATOR:'Куратор',WAREHOUSE:'Сотрудник склада',CUSTOMER_B2C:'Клиент B2C',CUSTOMER_B2B:'Партнёр B2B' };
const tabs = computed(() => [
  { id:'ALL', label:'Все', count:result.value.totals.all }, { id:'STAFF',label:'Сотрудники',count:result.value.totals.staff },
  { id:'B2C',label:'Клиенты B2C',count:result.value.totals.b2c }, { id:'B2B',label:'Партнёры B2B',count:result.value.totals.b2b },
]);

async function load() {
  busy.value = true; error.value = '';
  try {
    result.value = await $fetch('/system-settings/accounts', { baseURL: config.public.apiBase, headers: headers.value, query: { type:type.value, search:search.value || undefined, page:page.value, limit:30 } });
    requests.value = await $fetch<any[]>('/system-settings/profile-change-requests', { baseURL: config.public.apiBase, headers: headers.value });
  } catch (exception:any) { error.value = messageOf(exception); }
  finally { busy.value = false; }
}
function selectType(value:any){ type.value=value; page.value=1; load(); }
function openAccount(item:any){ selected.value=item; resetInfo.value=null; error.value=''; Object.assign(edit,{firstName:item.firstName||'',lastName:item.lastName||'',email:item.email||'',phone:item.phone||''}); Object.assign(temporary,{currentAdminPassword:'',temporaryPassword:''}); }
async function updateAccount(change:any = edit){
  if(!selected.value) return;
  await act(async()=>{ await $fetch(`/system-settings/accounts/${selected.value.id}`,{baseURL:config.public.apiBase,method:'PATCH',headers:headers.value,body:change}); await load(); selected.value={...selected.value,...change}; showNotice('Учётная запись обновлена'); });
}
async function createReset(){
  await act(async()=>{ resetInfo.value=await $fetch(`/system-settings/accounts/${selected.value.id}/password-reset`,{baseURL:config.public.apiBase,method:'POST',headers:headers.value}); showNotice('Одноразовая ссылка создана на 1 час'); });
}
async function setTemporary(){
  await act(async()=>{ await $fetch(`/system-settings/accounts/${selected.value.id}/temporary-password`,{baseURL:config.public.apiBase,method:'POST',headers:headers.value,body:temporary}); temporary.currentAdminPassword='';temporary.temporaryPassword='';await load();showNotice('Временный пароль установлен, все сессии завершены'); });
}
async function moveToTrash(item:any){
  selected.value=item;
  await act(async()=>{await $fetch(`/data-lifecycle/USER/${item.id}/trash`,{baseURL:config.public.apiBase,method:'POST',headers:headers.value,body:{reason:'Удалено администратором из реестра учётных записей'}});selected.value=null;await load();showNotice('Учётная запись перемещена в корзину')});
}
async function review(request:any,status:'APPROVED'|'REJECTED'){
  await act(async()=>{ await $fetch(`/system-settings/profile-change-requests/${request.id}/review`,{baseURL:config.public.apiBase,method:'POST',headers:headers.value,body:{status}});await load();showNotice(status==='APPROVED'?'Изменения подтверждены':'Запрос отклонён'); });
}
function accountMenu(event:MouseEvent,item:any){const name=[item.firstName,item.lastName].filter(Boolean).join(' ')||item.email;openContextMenu(event,name,[{label:'Открыть карточку',icon:'open',action:()=>openAccount(item)},{label:'Копировать email',icon:'copy',action:()=>copyText(item.email,'Email скопирован')},{label:item.isActive?'Заблокировать':'Разблокировать',icon:'block',separator:true,danger:item.isActive,disabled:item.id===user.value?.id,confirm:item.isActive?`Заблокировать «${name}» и завершить все сессии?`:undefined,action:()=>{selected.value=item;updateAccount({isActive:!item.isActive})}},{label:'Переместить в корзину',icon:'archive',danger:true,disabled:item.id===user.value?.id,confirm:`Переместить учётную запись «${name}» в корзину? Доступ будет немедленно закрыт.`,action:()=>moveToTrash(item)}],roleLabels[item.role]);}
async function act(callback:()=>Promise<void>){busy.value=true;error.value='';try{await callback()}catch(exception:any){error.value=messageOf(exception)}finally{busy.value=false}}
function messageOf(exception:any){return exception?.data?.message||exception?.message||'Не удалось выполнить действие'}
function showNotice(value:string){notice.value=value;setTimeout(()=>notice.value='',2600)}
function personName(item:any){return [item.firstName,item.lastName].filter(Boolean).join(' ')||'Без имени'}
watch(search,()=>{if(searchTimer)clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page.value=1;load()},350)});
onMounted(load);
</script>

<template>
  <section class="accounts-panel">
    <div class="account-summary"><button v-for="tab in tabs" :key="tab.id" :class="{active:type===tab.id}" @click="selectType(tab.id)"><span>{{tab.label}}</span><strong>{{tab.count}}</strong></button></div>
    <div v-if="requests.length" class="requests"><header><div><p>ТРЕБУЮТ РЕШЕНИЯ</p><h2>Запросы на изменение данных</h2></div><b>{{requests.length}}</b></header><article v-for="request in requests" :key="request.id"><div class="request-person"><i>{{(request.user.firstName||request.user.email).slice(0,1).toUpperCase()}}</i><span><strong>{{personName(request.user)}}</strong><small>{{request.user.email}} · {{new Date(request.createdAt).toLocaleString('ru-RU')}}</small></span></div><div class="changes"><span v-if="request.requestedData.firstName">Имя: <b>{{request.requestedData.firstName}}</b></span><span v-if="request.requestedData.lastName">Фамилия: <b>{{request.requestedData.lastName}}</b></span><span v-if="request.requestedData.phone">Телефон: <b>{{request.requestedData.phone}}</b></span></div><div class="request-actions"><button title="Подтвердить" @click="review(request,'APPROVED')"><Check :size="16"/></button><button title="Отклонить" @click="review(request,'REJECTED')"><X :size="16"/></button></div></article></div>
    <div class="accounts-card">
      <header><div><p>ЕДИНЫЙ РЕЕСТР</p><h2>Учётные записи платформы</h2><span>Сотрудники, покупатели сайта и партнёры B2B в одном защищённом контуре</span></div><label><Search :size="16"/><input v-model.trim="search" placeholder="Имя, email, телефон или компания"/></label></header>
      <div class="account-table"><div class="account-row head"><span>Пользователь</span><span>Тип</span><span>Организация</span><span>Сессии</span><span>Состояние</span></div><button v-for="item in result.items" :key="item.id" class="account-row" @click="openAccount(item)" @contextmenu.prevent="accountMenu($event,item)"><span class="account-person"><i><img v-if="item.avatarUrl" :src="new URL(item.avatarUrl,config.public.apiBase).toString()" alt=""/><template v-else>{{(item.firstName||item.email).slice(0,1).toUpperCase()}}</template></i><span><strong>{{personName(item)}}</strong><small>{{item.email}}<template v-if="item.phone"> · {{item.phone}}</template></small></span></span><span><em :class="item.accountType.toLowerCase()">{{item.accountType==='STAFF'?'Сотрудник':item.accountType==='B2B'?'B2B':'B2C'}}</em><small>{{roleLabels[item.role]}}</small></span><span>{{item.b2bProfile?.companyName||item.organizationMemberships?.[0]?.organization?.name||'—'}}</span><span>{{item._count.sessions}}</span><span :class="item.isActive?'state-active':'state-blocked'">{{item.isActive?'Активна':'Заблокирована'}}</span></button><div v-if="!result.items.length&&!busy" class="empty"><Users :size="26"/><span>Учётные записи не найдены</span></div></div>
      <footer><span>Показано {{result.items.length}} из {{result.total}}</span><div><button :disabled="page<=1" @click="page--;load()"><ChevronLeft :size="16"/></button><b>{{page}} / {{result.pages}}</b><button :disabled="page>=result.pages" @click="page++;load()"><ChevronRight :size="16"/></button></div></footer>
    </div>
    <Teleport to="body"><div v-if="selected" class="account-backdrop" @mousedown.self="selected=null"><aside class="account-drawer"><header><div><p>УЧЁТНАЯ ЗАПИСЬ</p><h2>{{personName(selected)}}</h2><span>{{roleLabels[selected.role]}}</span></div><button @click="selected=null"><X :size="19"/></button></header><div class="drawer-body"><section><div class="section-title"><div><h3>Контактные данные</h3><p>Изменения применяются сразу и попадают в журнал аудита.</p></div><Users :size="18"/></div><div class="fields"><label><span>Имя</span><input v-model.trim="edit.firstName"/></label><label><span>Фамилия</span><input v-model.trim="edit.lastName"/></label><label class="wide"><span>Email</span><input v-model.trim="edit.email" type="email"/></label><label class="wide"><span>Телефон</span><input v-model.trim="edit.phone"/></label></div><button class="primary" @click="updateAccount()">Сохранить данные</button></section><section><div class="section-title"><div><h3>Доступ</h3><p>Блокировка немедленно завершает активные сессии.</p></div><ShieldCheck :size="18"/></div><div class="access-state"><span><strong>{{selected.isActive?'Доступ разрешён':'Доступ заблокирован'}}</strong><small>Активных сессий: {{selected._count.sessions}}</small></span><button :disabled="selected.id===user?.id" @click="updateAccount({isActive:!selected.isActive})"><UserRoundX v-if="selected.isActive" :size="16"/><UserRoundCheck v-else :size="16"/>{{selected.isActive?'Заблокировать':'Разблокировать'}}</button></div></section><section><div class="section-title"><div><h3>Восстановление пароля</h3><p>Пароли никогда не отображаются и не отправляются в открытом виде.</p></div><KeyRound :size="18"/></div><button class="secondary full" @click="createReset"><Link2 :size="16"/>Создать одноразовую ссылку</button><div v-if="resetInfo" class="reset-link"><input :value="resetInfo.resetUrl" readonly/><button title="Копировать" @click="copyText(resetInfo.resetUrl,'Ссылка скопирована')"><Clipboard :size="16"/></button><small>Действует до {{new Date(resetInfo.expiresAt).toLocaleString('ru-RU')}}. Отправка письмом появится после подключения почтового провайдера.</small></div><div class="temp-password"><h4>Или установить временный пароль</h4><label><span>Ваш пароль администратора</span><input v-model="temporary.currentAdminPassword" type="password"/></label><label><span>Временный пароль для пользователя</span><input v-model="temporary.temporaryPassword" type="password" placeholder="Не менее 10 символов"/></label><button class="secondary full" :disabled="!temporary.currentAdminPassword||!temporary.temporaryPassword" @click="setTemporary"><LockKeyhole :size="16"/>Установить и завершить сессии</button></div></section></div></aside></div></Teleport>
    <p v-if="error" class="account-error">{{error}}</p><p v-if="notice" class="account-notice"><Check :size="15"/>{{notice}}</p>
  </section>
</template>

<style scoped>
.accounts-panel{display:grid;gap:18px;color:var(--sb-text)}.account-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.account-summary button{height:72px;border:1px solid var(--sb-line);background:#fff;padding:13px 16px;text-align:left;display:flex;align-items:center;justify-content:space-between;cursor:pointer}.account-summary button.active{border-color:var(--sb-ink);box-shadow:inset 3px 0 var(--sb-coral)}.account-summary span{font-size:10px;color:var(--sb-muted)}.account-summary strong{font-size:22px;font-weight:500}.accounts-card,.requests{background:#fff;border:1px solid var(--sb-line)}.accounts-card>header,.requests>header{min-height:105px;padding:22px 26px;display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid var(--sb-line);box-sizing:border-box}.accounts-card header p,.requests header p,.account-drawer header p{margin:0 0 7px;color:var(--sb-coral);font-size:9px;font-weight:700;letter-spacing:.15em}.accounts-card h2,.requests h2{margin:0 0 6px;font-size:19px}.accounts-card header span{color:var(--sb-muted);font-size:9px}.accounts-card header label{width:min(340px,42%);height:42px;border:1px solid var(--sb-line);display:flex;align-items:center;gap:9px;padding:0 12px;box-sizing:border-box;color:var(--sb-muted)}.accounts-card header input{width:100%;border:0;outline:0;font-size:10px}.account-row{width:100%;min-height:67px;padding:10px 26px;box-sizing:border-box;display:grid;grid-template-columns:2fr .9fr 1.1fr .45fr .75fr;gap:14px;align-items:center;border:0;border-bottom:1px solid var(--sb-line);background:#fff;text-align:left;color:var(--sb-text);font-size:10px}.account-row:not(.head){cursor:pointer}.account-row:not(.head):hover{background:#fafafa}.account-row.head{min-height:43px;color:var(--sb-muted);font-size:8px;text-transform:uppercase;letter-spacing:.06em}.account-person{display:flex;align-items:center;gap:10px;min-width:0}.account-person>i{width:34px;height:34px;border-radius:50%;background:var(--sb-ink);color:#fff;display:grid;place-items:center;font-style:normal;overflow:hidden}.account-person img{width:100%;height:100%;object-fit:cover}.account-person>span,.account-row>span:nth-child(2){display:grid;gap:4px;min-width:0}.account-person strong{overflow:hidden;text-overflow:ellipsis}.account-person small,.account-row small{font-size:8px;color:var(--sb-muted);overflow:hidden;text-overflow:ellipsis}.account-row em{justify-self:start;padding:3px 6px;font-size:8px;font-style:normal;background:#eef1f4}.account-row em.b2b{background:#fff0ed;color:#a94334}.account-row em.b2c{background:#edf6f1;color:#257d58}.state-active{color:var(--sb-success)}.state-blocked{color:var(--sb-danger)}.accounts-card>footer{height:52px;padding:0 26px;display:flex;align-items:center;justify-content:space-between;color:var(--sb-muted);font-size:9px}.accounts-card footer div{display:flex;align-items:center;gap:10px}.accounts-card footer button{width:30px;height:30px;border:1px solid var(--sb-line);background:#fff}.accounts-card footer b{color:var(--sb-text);font-weight:500}.empty{height:150px;display:grid;place-items:center;align-content:center;gap:9px;color:var(--sb-muted);font-size:10px}.requests>header{min-height:85px}.requests header b{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:var(--sb-coral);color:#fff;font-size:11px}.requests article{min-height:67px;padding:10px 24px;display:grid;grid-template-columns:1.2fr 1.5fr auto;gap:20px;align-items:center;border-bottom:1px solid var(--sb-line)}.requests article:last-child{border-bottom:0}.request-person{display:flex;align-items:center;gap:9px}.request-person i{width:31px;height:31px;border-radius:50%;display:grid;place-items:center;background:var(--sb-ink);color:#fff;font-style:normal;font-size:10px}.request-person span{display:grid;gap:4px}.request-person strong{font-size:10px}.request-person small,.changes span{font-size:8px;color:var(--sb-muted)}.changes{display:flex;gap:12px;flex-wrap:wrap}.changes b{color:var(--sb-text)}.request-actions{display:flex;gap:5px}.request-actions button{width:32px;height:32px;border:1px solid var(--sb-line);background:#fff;display:grid;place-items:center}.request-actions button:first-child{color:var(--sb-success)}.request-actions button:last-child{color:var(--sb-danger)}.account-backdrop{position:fixed;z-index:1250;inset:0;background:#1011137a;display:flex;justify-content:flex-end;font-family:var(--sb-font)}.account-drawer{width:min(560px,100vw);height:100%;background:var(--sb-bg);box-shadow:-18px 0 55px #0003;overflow:auto}.account-drawer>header{height:95px;padding:0 28px;background:#fff;border-bottom:1px solid var(--sb-line);display:flex;align-items:center;justify-content:space-between}.account-drawer h2{margin:0 0 5px;font-size:22px}.account-drawer header span{font-size:9px;color:var(--sb-muted)}.account-drawer header button{width:38px;height:38px;border:1px solid var(--sb-line);background:#fff}.drawer-body{padding:22px;display:grid;gap:16px}.drawer-body section{padding:20px;background:#fff;border:1px solid var(--sb-line);display:grid;gap:17px}.section-title{display:flex;justify-content:space-between}.section-title h3{margin:0 0 5px;font-size:14px}.section-title p{margin:0;font-size:8px;line-height:1.5;color:var(--sb-muted)}.section-title svg{color:var(--sb-coral)}.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.fields .wide{grid-column:1/-1}.fields label,.temp-password label{display:grid;gap:6px}.fields label span,.temp-password label span{font-size:8px;color:var(--sb-muted)}.fields input,.temp-password input,.reset-link input{height:41px;border:1px solid var(--sb-line);padding:0 10px;box-sizing:border-box;font-size:10px;outline:0}.primary,.secondary{height:40px;padding:0 14px;border:1px solid var(--sb-ink);font-size:10px;justify-self:start}.primary{background:var(--sb-ink);color:#fff}.secondary{background:#fff;color:var(--sb-text);display:flex;align-items:center;justify-content:center;gap:8px}.full{width:100%}.access-state{display:flex;align-items:center;justify-content:space-between;gap:15px}.access-state span{display:grid;gap:4px}.access-state strong{font-size:10px}.access-state small{font-size:8px;color:var(--sb-muted)}.access-state button{height:38px;border:1px solid var(--sb-line);background:#fff;padding:0 12px;display:flex;align-items:center;gap:7px;font-size:9px}.reset-link{display:grid;grid-template-columns:1fr 40px}.reset-link button{border:1px solid var(--sb-line);border-left:0;background:#fff}.reset-link small{grid-column:1/-1;margin-top:7px;font-size:8px;line-height:1.5;color:var(--sb-muted)}.temp-password{padding-top:16px;border-top:1px solid var(--sb-line);display:grid;gap:12px}.temp-password h4{margin:0;font-size:10px}.account-error,.account-notice{position:fixed;z-index:1400;right:26px;bottom:22px;padding:12px 14px;margin:0;box-shadow:var(--sb-shadow);font-size:10px}.account-error{background:#fff0ed;color:#a83e31}.account-notice{background:var(--sb-success);color:#fff;display:flex;align-items:center;gap:7px}@media(max-width:900px){.account-summary{grid-template-columns:1fr 1fr}.account-row{grid-template-columns:1.5fr .8fr .6fr}.account-row>span:nth-child(3),.account-row>span:nth-child(4){display:none}}@media(max-width:620px){.account-summary{grid-template-columns:1fr}.accounts-card>header{align-items:flex-start;flex-direction:column}.accounts-card header label{width:100%}.account-row{grid-template-columns:1fr .7fr}.account-row>span:nth-child(5){display:none}.fields{grid-template-columns:1fr}.fields .wide{grid-column:auto}}
</style>
